package rules

import (
	"strings"

	"github.com/synacktiv/octoscan/common"

	"github.com/rhysd/actionlint"
)

type RuleDangerousCheckout struct {
	actionlint.RuleBase
	filterTriggers []string
	skip           bool
}

// NewRuleDangerousCheckout creates new RuleDangerousCheckout instance.
